import {strictJSON} from './firmware-compare.js';
import {purlIdentity,componentIdentity} from './components.js';
const text=(v,max,required=false)=>{if(v===undefined&&!required)return '';if(typeof v!=='string'||v.length>max||required&&!v.trim())throw Error('Invalid or oversized advisory field.');return v;};
const date=(v,required=false)=>{if(v===undefined&&!required)return '';if(typeof v!=='string'||!/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d+)?Z$/.test(v)||(!Number.isFinite(Date.parse(v))||new Date(v).toISOString().slice(0,19)!==v.slice(0,19)))throw Error('Advisories require an explicit UTC modification date.');return v;};
const array=(v,max)=>{if(v===undefined)return [];if(!Array.isArray(v)||v.length>max)throw Error('Advisory collection exceeds bounds.');return v;};
export function parseAdvisories(input){if(JSON.stringify(input)?.length>1024*1024)throw Error('Use advisory JSON of 1 MiB or less.');const list=Array.isArray(input?.vulns)?input.vulns:[input];if(!list.length||list.length>100)throw Error('Import 1–100 OSV records.');const ids=new Set();return list.map(v=>{
 if(!v||typeof v!=='object')throw Error('Choose OSV JSON records.');const advisoryId=text(v.id,200,true);if(!/^[a-zA-Z0-9:_.-]+$/.test(advisoryId)||ids.has(advisoryId))throw Error('Invalid or duplicate advisory ID.');ids.add(advisoryId);
 const affected=array(v.affected,100).map(a=>{if(!a?.package)throw Error('An affected package identity is required.');const p={name:text(a.package.name,512),ecosystem:text(a.package.ecosystem,100),purl:text(a.package.purl,2048)};if(p.purl)purlIdentity(p.purl);if(!p.purl&&(!p.name||!p.ecosystem))throw Error('Package needs a PURL or ecosystem and name.');return {package:p,versions:array(a.versions,1000).map(x=>text(x,200,true)),ranges:array(a.ranges,100).map(r=>{if(!['SEMVER','ECOSYSTEM','GIT'].includes(r.type))throw Error('Unknown advisory range type.');const events=array(r.events,100).map(e=>{const keys=Object.keys(e||{});if(keys.length!==1||!['introduced','fixed','last_affected','limit'].includes(keys[0]))throw Error('Invalid advisory range event.');return {[keys[0]]:text(e[keys[0]],200,true)};});if(!events.length)throw Error('Empty advisory range.');return {type:r.type,repo:text(r.repo,2048),events};})};});
 return {advisoryId,modified:date(v.modified,true),published:date(v.published),withdrawn:date(v.withdrawn),summary:text(v.summary,2000),details:text(v.details,50000),aliases:array(v.aliases,100).map(x=>text(x,200,true)),references:array(v.references,100).map(r=>{const url=text(r.url,2048,true);if(!/^https?:\/\//.test(url))throw Error('Advisory reference must be an HTTP(S) URL.');const parsed=new URL(url);if(parsed.username||parsed.password)throw Error('Advisory references cannot embed credentials.');return {type:text(r.type,100),url};}),affected};
 });}
const ecosystems={npm:'npm',pypi:'PyPI',cargo:'crates.io',maven:'Maven',golang:'Go',nuget:'NuGet'};
export function advisoryCandidates(components,advisories){const rows=[],cache=new Map();const identity=value=>{if(!cache.has(value)){try{cache.set(value,purlIdentity(value));}catch{cache.set(value,null);}}return cache.get(value);};for(const c of components)for(const a of advisories){const matches=a.record.affected.filter(x=>{const p=x.package;if(p.purl){try{return !!identity(p.purl)&&identity(p.purl).key===identity(c.purl)?.key;}catch{return false;}}if(c.ecosystem)return c.ecosystem===p.ecosystem&&[c.group,c.name].filter(Boolean).join('/')===p.name;try{const i=identity(c.purl);return !!i&&ecosystems[i.type]===p.ecosystem&&(i.type==='maven'?i.path.replace('/',':'):i.path)===p.name;}catch{return false;}});if(matches.length){const listed=!!c.version&&matches.some(x=>x.versions.includes(c.version));rows.push({componentId:c.id,advisoryId:a.id,basis:a.record.withdrawn?'Withdrawn record — historical review only':listed?'Version explicitly listed':matches.some(x=>x.ranges.length)?'Range review required':'Version not listed; applicability unknown',identity:componentIdentity(c).strength,listed,ranges:matches.flatMap(x=>x.ranges)});if(rows.length>5000)throw Error('Too many advisory candidates; narrow the inventory.');}}return rows;}
export const REVIEW_STATES=['Unreviewed','Affected','Not affected','Fixed','Inconclusive'];
export function validateAdvisoryProject(p){
 p.advisories??=[];p.advisoryReviews??=[];if(!Array.isArray(p.advisories)||p.advisories.length>100||!Array.isArray(p.advisoryReviews)||p.advisoryReviews.length>500)throw Error('Advisory history exceeds supported bounds.');const ids=new Set(),parsedOriginals=new Map(),same=(id,device)=>p.evidence.find(e=>e.id===id&&e.deviceId===device);
 for(const a of p.advisories){if(!a||!/^adv_[a-z0-9_]+$/i.test(a.id)||ids.has(a.id)||!same(a.evidenceId,a.deviceId)||!p.devices.some(d=>d.id===a.deviceId)||!Number.isFinite(Date.parse(a.importedAt)))throw Error('Invalid advisory evidence reference.');ids.add(a.id);let original;try{original=strictJSON(new TextDecoder().decode(Uint8Array.from(atob(same(a.evidenceId,a.deviceId).data.split(',')[1]),c=>c.charCodeAt(0))));}catch{throw Error('Invalid advisory original.');}if(!parsedOriginals.has(a.evidenceId))parsedOriginals.set(a.evidenceId,parseAdvisories(original));const normalized=parsedOriginals.get(a.evidenceId).find(r=>r.advisoryId===a.record?.advisoryId);if(!normalized||JSON.stringify(normalized)!==JSON.stringify(a.record))throw Error('Advisory differs from its preserved original.');}
 for(const r of p.advisoryReviews){const a=p.advisories.find(a=>a.id===r.advisoryId&&a.deviceId===r.deviceId),c=p.components.find(c=>c.id===r.componentId&&c.deviceId===r.deviceId);if(!a||!c||!same(c.evidenceId,r.deviceId)||!/^review_[a-z0-9_]+$/i.test(r.id)||ids.has(r.id)||!REVIEW_STATES.includes(r.status)||!Number.isFinite(Date.parse(r.createdAt))||typeof r.reviewer!=='string'||!r.reviewer.trim()||r.reviewer.length>200||typeof r.notes!=='string'||r.notes.length>8000||r.status!=='Unreviewed'&&!r.notes.trim()||!Array.isArray(r.evidenceIds)||r.evidenceIds.length>20||new Set(r.evidenceIds).size!==r.evidenceIds.length||r.evidenceIds.some(id=>!same(id,r.deviceId)))throw Error('Invalid advisory applicability review.');ids.add(r.id);if(!advisoryCandidates([c],[a]).length)throw Error('Review package no longer matches the advisory.');if(['Affected','Not affected','Fixed'].includes(r.status)&&!r.evidenceIds.some(id=>id!==a.evidenceId&&id!==c.evidenceId))throw Error('A conclusion requires separate device assessment evidence.');if(r.componentIdentity!==componentIdentity(c).key||r.componentVersion!==(c.version||'')||r.componentEvidenceId!==c.evidenceId)throw Error('Review component snapshot no longer matches.');}
 for(const d of p.devices)advisoryCandidates(p.components.filter(c=>c.deviceId===d.id),p.advisories.filter(a=>a.deviceId===d.id));
 return p;
}
